package com.huy.enterprise.risk; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RiskEventStatus; import com.huy.enterprise.order.PurchaseOrderRepository; import com.huy.enterprise.product.ProductRepository; import com.huy.enterprise.shipment.ShipmentRepository; import com.huy.enterprise.supplier.SupplierRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*; @Service @RequiredArgsConstructor public class RiskEventService {private final RiskEventRepository repo;private final SupplierRepository suppliers;private final ProductRepository products;private final PurchaseOrderRepository orders;private final ShipmentRepository shipments; RiskEvent entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Risk event not found: "+id));}List<RiskResponse> all(){return repo.findAll().stream().map(RiskResponse::from).toList();}RiskResponse get(UUID id){return RiskResponse.from(entity(id));}@Transactional RiskResponse save(UUID id,RiskRequest x){var r=id==null?new RiskEvent():entity(id);r.setTitle(x.title());r.setRiskType(x.riskType());r.setImpactLevel(x.impactLevel());r.setDescription(x.description());r.setDetectedAt(x.detectedAt()==null?OffsetDateTime.now():x.detectedAt());r.setStatus(x.status()==null?RiskEventStatus.OPEN:x.status());r.setSupplier(x.supplierId()==null?null:suppliers.findById(x.supplierId()).orElseThrow(()->new ResourceNotFoundException("Supplier not found: "+x.supplierId())));r.setProduct(x.productId()==null?null:products.findById(x.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found: "+x.productId())));r.setPurchaseOrder(x.purchaseOrderId()==null?null:orders.findById(x.purchaseOrderId()).orElseThrow(()->new ResourceNotFoundException("Purchase order not found: "+x.purchaseOrderId())));r.setShipment(x.shipmentId()==null?null:shipments.findById(x.shipmentId()).orElseThrow(()->new ResourceNotFoundException("Shipment not found: "+x.shipmentId())));return RiskResponse.from(repo.save(r));}@Transactional RiskResponse status(UUID id,RiskStatusRequest x){var r=entity(id);r.setStatus(x.status());return RiskResponse.from(repo.save(r));}}
